public protocol FluxEngineProtocol: AnyObject, Sendable {
    
    /**
     * Subscription status from the provider (Xtream only).
     */
    func accountInfo(sourceId: Int64) async throws  -> AccountInfo?
    
    func categories(sourceId: Int64, kind: ContentKind) throws  -> [Category]
    
    func channel(sourceId: Int64, kind: ContentKind, channelId: String) throws  -> Channel
    
    func channels(sourceId: Int64, kind: ContentKind, categoryId: String) throws  -> [Channel]
    
    func clearHistory(sourceId: Int64) throws 
    
    /**
     * Favorite ids (including channels not in the current catalog), for backups.
     */
    func favoriteIds(sourceId: Int64, kind: ContentKind) throws  -> [String]
    
    func favorites(sourceId: Int64, kind: ContentKind) throws  -> [Channel]
    
    /**
     * Programmes overlapping `[from, to)` (Unix seconds) per XMLTV id.
     */
    func guide(sourceId: Int64, epgIds: [String], from: Int64, to: Int64) throws  -> [GuideRow]
    
    /**
     * What is on now and next for each XMLTV id (in the same order).
     */
    func nowNext(sourceId: Int64, epgIds: [String]) throws  -> [NowNext]
    
    /**
     * Prepare playback and return a URL for AVPlayer. Live MPEG-TS streams are served as HLS
     * by the local media server, and so are movies stored as MPEG-TS; MP4 movies are passed
     * through. Blocks briefly for movies while the file is inspected. Starting a stream always
     * stops the previous upstream connection first, so single-connection accounts keep working
     * when zapping.
     */
    func play(sourceId: Int64, kind: ContentKind, channelId: String) throws  -> Playback
    
    /**
     * State of the current live stream, for status overlays and error messages.
     */
    func playbackStatus()  -> PlaybackStatus
    
    func recent(sourceId: Int64, kind: ContentKind, limit: UInt32) throws  -> [Channel]
    
    /**
     * Refresh the catalog and then the guide (only stale parts unless `force`).
     * Poll [`refresh_progress`](Self::refresh_progress) for status while it runs.
     */
    func refresh(sourceId: Int64, force: Bool) async throws  -> RefreshOutcome
    
    func refreshProgress(sourceId: Int64)  -> RefreshProgress?
    
    /**
     * Restore favorites from a backup (adds; never removes).
     */
    func restoreFavorites(sourceId: Int64, kind: ContentKind, channelIds: [String]) throws 
    
    /**
     * Ranked search; every query word must match.
     */
    func search(sourceId: Int64, kind: ContentKind, query: String, limit: UInt32) throws  -> [Channel]
    
    func source(sourceId: Int64) throws  -> SourceInfo
    
    /**
     * Which parts of a source are out of date.
     */
    func staleness(sourceId: Int64) throws  -> Staleness
    
    /**
     * Close the upstream connection (player dismissed).
     */
    func stopPlayback() 
    
    /**
     * Make the database match the Keychain: add or update every account (keeping cached
     * catalogs, favorites and history), remove sources whose account is gone, and load the
     * passwords into memory for this session.
     */
    func syncAccounts(accounts: [SavedAccount]) throws  -> [SourceInfo]
    
    /**
     * Returns the new favorite state.
     */
    func toggleFavorite(sourceId: Int64, kind: ContentKind, channelId: String) throws  -> Bool
    
    /**
     * Normalize and validate account input against the provider (Xtream logins are checked).
     * Pasted Xtream `get.php` links become Xtream accounts.
     */
    func validateAccount(input: AccountInput) async throws  -> ValidatedAccount
    
    /**
     * Core version string (`FluxTV/x.y.z`).
     */
    func version()  -> String
    
}
