public struct FfiConverterTypeFluxEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = FluxEngine

    public static func lift(_ handle: UInt64) throws -> FluxEngine {
        return FluxEngine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: FluxEngine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FluxEngine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: FluxEngine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


