public enum ContentKind: Equatable, Hashable {
    
    case live
    case movie
    case series





}

#if compiler(>=6)
extension ContentKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeContentKind: FfiConverterRustBuffer {
    typealias SwiftType = ContentKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ContentKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .live
        
        case 2: return .movie
        
        case 3: return .series
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ContentKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .live:
            writeInt(&buf, Int32(1))
        
        
        case .movie:
            writeInt(&buf, Int32(2))
        
        
        case .series:
            writeInt(&buf, Int32(3))
        
        }
    }
}


