public 
enum FluxError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Network(message: String
    )
    case Auth(message: String
    )
    case NotFound(message: String
    )
    case Invalid(message: String
    )
    case Data(message: String
    )
    case Internal(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FluxError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFluxError: FfiConverterRustBuffer {
    typealias SwiftType = FluxError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FluxError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Network(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Auth(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Invalid(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Data(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FluxError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Network(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Auth(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NotFound(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Invalid(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Data(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


